import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

// Primary key generated by Postgres itself (gen_random_uuid is built in since PG 13), so rows
// inserted by raw SQL or other tools get valid ids too.
export const id = () => uuid('id').primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

// The value is kept fresh by the `set_updated_at` trigger (migration 0000), not by app code.
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();

// Case-insensitive text: the unique index on an email then treats "A@x.com" and "a@x.com" as one.
export const citext = customType<{ data: string }>({
  dataType() {
    return 'citext';
  },
});
